// Guardrail Ebene 2: gültige Kundenkennung, gültige paket_id, die zu diesem Auftrag gehört. Die Kundenkennung setzt der Hauptworkflow fest.
// Warum test_fehler: nur für Tests, 'foto' erzwingt den Weg ohne Pixabay-Foto, 'render' lässt Gotenberg ausfallen. Der Hauptworkflow übergibt das Feld nie.
const j = $input.first().json;
const kuerzel = String(j.kuerzel ?? '').trim().toLowerCase();
const paketId = String(j.paket_id ?? '').trim();
const trace = String(j.trace_id ?? '').trim().slice(0, 60) || 'ohne_trace_id';
const t = String(j.test_fehler ?? '').trim();
const test = (t === 'foto' || t === 'render') ? t : '';
let fehler = '';
if (!/^[a-z0-9-]{2,40}$/.test(kuerzel)) fehler = 'FEHLER: ungültige Kundenkennung, keine Bilder erstellt.';
else if (!/^paket-[A-Za-z0-9_-]{3,100}$/.test(paketId)) fehler = 'FEHLER: paket_id fehlt oder ist ungültig, keine Bilder erstellt. Rufe zuerst Text_schreiben auf und nutze die paket_id aus dessen Antwort.';
else if (trace !== 'ohne_trace_id' && !paketId.startsWith('paket-' + trace + '-')) fehler = 'FEHLER: Diese paket_id gehört nicht zu diesem Auftrag, keine Bilder erstellt.';
return [{ json: { kuerzel: kuerzel, paket_id: paketId, trace_id: trace, test_fehler: test, eingabe_ok: fehler === '', fehler_text: fehler } }];

// Zweck (Werkzeug 4, v01): Paket und Kundenprofil zusammenführen, Markenfarben und Schriften festlegen; fehlt etwas, endet der Lauf mit NICHT_GEFUNDEN oder FEHLER.
// Herkunft: gekürzte Fassung von "Branding-Variante wählen" aus Projekt 1 (Standardwerte aus dem Kundenprofil, ohne Layout 4).
const e = $('Eingabe prüfen [Code]').first().json;
const pRow = $('Paket lesen [Supabase]').first().json || {};
const kunde = $input.first().json || {};
const stopp = t => [{ json: { bereit: false, fehler_text: t } }];
if (!pRow.paket_id) return stopp('NICHT_GEFUNDEN: Für diese paket_id liegt kein Paket vor, keine Bilder erstellt.');
if (pRow.paket_id !== e.paket_id || pRow.kuerzel !== e.kuerzel) return stopp('FEHLER: Das Paket gehört nicht zu diesem Kunden, keine Bilder erstellt.');
if (!kunde.kuerzel || kunde.kuerzel !== e.kuerzel) return stopp('NICHT_GEFUNDEN: Für diesen Kunden gibt es kein aktives Branding, keine Bilder erstellt.');
let paket = pRow.paket;
if (typeof paket === 'string') { try { paket = JSON.parse(paket); } catch (x) { return stopp('FEHLER: Das gespeicherte Paket ist nicht lesbar, keine Bilder erstellt.'); } }
const folien = paket && Array.isArray(paket.slides) ? paket.slides : [];
if (folien.length < 5 || folien.length > 8 || folien.some(f => !f || typeof f.heading !== 'string' || typeof f.text !== 'string' || (!f.heading.trim() && !f.text.trim()))) return stopp('FEHLER: Das Paket hat keine gültigen Folien (5 bis 8 mit Überschrift und Text), keine Bilder erstellt.');
let b = kunde.branding_pack;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (x) { b = {}; } }
if (!b || typeof b !== 'object' || Array.isArray(b)) b = {};
const farbe = (v, d) => (/^#[0-9a-fA-F]{6}$/.test(v || '') ? v : d);
const bf = b.farben || {};
const farben = {
  primaer: farbe(bf.primaer || kunde.farbe_primaer, '#15774E'), sekundaer: farbe(bf.sekundaer || kunde.farbe_sekundaer, '#515F56'),
  akzent: farbe(bf.akzent || kunde.farbe_akzent, '#22A26F'), hintergrund: farbe(bf.hintergrund || kunde.farbe_hintergrund, '#F4FBF7'),
  text: farbe(bf.text || kunde.farbe_text, '#111C16') };
const bs = b.schriften || {};
const name = String(b.markenname || kunde.name || 'Kunde').slice(0, 60);
return [{ json: { bereit: true, kuerzel: e.kuerzel, paket_id: e.paket_id, trace_id: e.trace_id, test_fehler: e.test_fehler, paket: paket,
  kunde: { name: name, farben: farben, schrift_titel: String(bs.titel || kunde.schrift_titel || 'DejaVu Sans'), schrift_text: String(bs.text || kunde.schrift_text || 'DejaVu Sans') },
  photo_query: String(paket.photo_query || '').trim().slice(0, 100) } }];

// Zweck (Werkzeug 4, v01): aus den Pixabay-Treffern ein passendes Foto wählen; Auth-, Timeout- und Leerantworten führen sichtbar zum KI-Bild.
// Herkunft: gekürzte Fassung von "Foto auswerten" aus Projekt 1 (ganze Wörter statt Teilzeichenketten, abstrakte Wörter zählen nicht, mindestens 2 passende Wörter).
const basis = $('Branding wählen [Code]').first().json;
const r = $input.first().json || {};
const frage = String(basis.photo_query || '').trim();
const st = Number(r.statusCode);
const hits = r.body && Array.isArray(r.body.hits) ? r.body.hits : [];
// Muster statt new URL: im Code-Knoten dieser Instanz verwarf new URL alle echten Treffer.
const safePhoto = s => typeof s === 'string' && /^https:\/\/(cdn\.)?pixabay\.com\/[^\s"'<>]*$/.test(s);
const safeLink = s => typeof s === 'string' && /^https:\/\/(www\.)?pixabay\.com\/[^\s"'<>]*$/.test(s);
const einzahl = w => w.length > 4 && w.endsWith('ies') ? w.slice(0, -3) + 'y' : (/(ch|sh|ss|x)es$/.test(w) ? w.slice(0, -2) : (w.length >= 4 && w.endsWith('s') && !w.endsWith('ss') ? w.slice(0, -1) : w));
const FUELL = new Set(['a', 'an', 'the', 'of', 'with', 'and', 'or', 'for', 'on', 'in', 'at', 'to', 'by', 'from', 'into', 'over', 'under', 'near']);
const ALLGEMEIN = new Set(['people', 'person', 'technology', 'tech', 'innovation', 'innovative', 'digital', 'automation', 'business'].map(einzahl));
const ABSTRAKT = new Set(['error', 'process', 'management', 'solution', 'strategy', 'efficiency', 'system', 'data', 'information', 'concept', 'idea', 'success', 'growth', 'quality', 'problem', 'tool', 'service', 'method', 'guide', 'tip', 'step', 'productivity', 'performance', 'benefit', 'future', 'time', 'experience', 'value', 'cost', 'result', 'goal', 'plan', 'change', 'trend', 'skill', 'knowledge', 'communication', 'security', 'risk', 'analysis', 'decision', 'marketing', 'trust', 'impact'].map(einzahl));
const woerterVon = s => String(s || '').toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(Boolean).map(einzahl);
const inhaltVon = s => Array.from(new Set(woerterVon(s).filter(w => !FUELL.has(w) && !ALLGEMEIN.has(w) && !ABSTRAKT.has(w) && (w.length >= 3 || /\d/.test(w)))));
const eigene = inhaltVon(frage);
let best = null, notiz = '';
if (eigene.length < 2) {
  notiz = 'Pixabay nicht ausgewertet (Suchbegriff "' + frage.slice(0, 40) + '" hat keine 2 konkreten Bildwörter), weiter mit KI-Bild.';
} else if (r.error || !(st >= 200 && st < 300) || !hits.length) {
  notiz = 'Pixabay lieferte keine Treffer oder die Anfrage scheiterte, weiter mit KI-Bild.';
} else {
  hits.forEach((h, pos) => {
    if (!h || !safePhoto(h.largeImageURL) || !safeLink(h.pageURL)) return;
    const tags = new Set(woerterVon(h.tags));
    const treffer = eigene.filter(w => tags.has(w));
    if (treffer.length < 2) return;
    if (!best || treffer.length > best.n) best = { h, n: treffer.length, pos };
  });
  if (!best) notiz = 'Pixabay ohne passenden Treffer (kein Treffer mit 2 passenden Schlagwörtern zu "' + frage.slice(0, 40) + '"), weiter mit KI-Bild.';
}
const p = best ? best.h : null;
const nutzerUrl = p && safeLink(p.userURL) ? p.userURL : '';
return [{ json: { ...basis, photo_ok: !!p, photo_url: p ? p.largeImageURL : '',
  photo_credit: p ? { photographer: String(p.user || ''), photographer_url: nutzerUrl, source: 'Pixabay', pixabay_url: p.pageURL, photo_id: p.id } : null,
  photo_note: notiz }, pairedItem: { item: 0 } }];

// Binäre Speichermodi über den n8n-Helper lesen, kein direkter Zugriff auf binary.data.
const basis = $('Foto auswerten [Code]').first().json;
const item = $input.first();
if (!item.binary?.foto) throw new Error('Foto-Download hat keine Binärdatei geliefert.');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'foto');
const jpeg = buffer.length > 3 && buffer[0] === 255 && buffer[1] === 216 && buffer[2] === 255;
const png = buffer.length > 8 && buffer.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]));
if ((!jpeg && !png) || buffer.length > 12 * 1024 * 1024) throw new Error('Foto ist kein JPEG/PNG oder größer als 12 MiB.');
return [{ json: { ...basis, photo_data_uri: 'data:' + (png ? 'image/png' : 'image/jpeg') + ';base64,' + buffer.toString('base64') }, pairedItem: { item: 0 } }];

// Zweck (Werkzeug 4, v01): je Folie und für das Einzelbild eine index.html im Kundenbranding bauen, Gotenberg macht daraus PNG 1080 x 1350.
// Herkunft: gekürzte Fassung der Bild-Vorlagen aus Projekt 1 (Layouts 1 bis 3: hybrid, thema, ablauf), ohne Layout 4, ohne Logo-Datei (Wortmarke).
// Warum Escaping: Texte stammen aus Modell und Paket, sie dürfen kein HTML in die Folie schmuggeln.
const B = 1080, H = 1350;
let bild = '', quelle = 'farbverlauf', credit = null, hinweis = '', ctx;
if ($('Bild-Fallback vorbereiten [Code]').isExecuted) {
  ctx = $('Bild-Fallback vorbereiten [Code]').first().json;
  hinweis = String(ctx.photo_note || '');
  try {
    const r = $('Einzelbild erzeugen [HTTP Request]').first().json;
    const b64 = r && r.result && r.result.image;
    if (typeof b64 === 'string' && b64.length > 100) { bild = 'data:' + (b64.startsWith('iVBOR') ? 'image/png' : 'image/jpeg') + ';base64,' + b64; quelle = 'flux'; }
    else hinweis = [hinweis, 'KI-Bild lieferte kein Bild, Farbverlauf'].filter(Boolean).join('; ');
  } catch (e) { hinweis = [hinweis, 'KI-Bild nicht aufgerufen, Farbverlauf'].filter(Boolean).join('; '); }
} else {
  ctx = $('Foto einbetten [Code]').first().json;
  if (!ctx.photo_data_uri) throw new Error('Foto fehlt im Kontext.');
  bild = ctx.photo_data_uri; quelle = 'pixabay'; credit = ctx.photo_credit;
}
const k = ctx.kunde;
const paket = ctx.paket;
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const c = k.farben;
const sauber = n => String(n || '').replace(/[^A-Za-z0-9 ÄÖÜäöüß-]/g, '');
const fTitel = "'" + sauber(k.schrift_titel) + "', 'DejaVu Sans', 'Liberation Sans', Arial, sans-serif";
const fText = "'" + sauber(k.schrift_text) + "', 'DejaVu Sans', 'Liberation Sans', Arial, sans-serif";
const folien = (paket.slides || []).map(f => ({ type: f.type, heading: String(f.heading || ''), text: String(f.text || '') }));
if (folien.length < 5 || folien.length > 8) throw new Error('Render-Liste verlangt 5 bis 8 Folien.');
const n = folien.length;
const W = n * B;
// Wortmarke statt Logo-Datei: Kreis mit dem ersten Buchstaben des Markennamens in den Markenfarben.
const ersterBuchstabe = esc(Array.from(String(k.name || '?'))[0].toUpperCase());
const logo = '<span class="wort">' + ersterBuchstabe + '</span>';
// Durchlaufendes Design: eine breite SVG-Fläche über alle Folien, jede Folie zeigt ihren Ausschnitt.
let welle = 'M0 ' + (H - 300), linie = 'M0 ' + (H - 400);
for (let x = 0; x <= W; x += 30) {
  welle += ' L' + x + ' ' + (H - 300 + Math.round(Math.sin(x / 520) * 70));
  linie += ' L' + x + ' ' + (H - 400 + Math.round(Math.sin(x / 520 + 1.3) * 80));
}
welle += ' L' + W + ' ' + H + ' L0 ' + H + ' Z';
let kreise = '';
for (let i = 0; i < n; i++) {
  const cx = i * B + (i % 2 ? 140 : 940), cy = i % 2 ? 250 : 320;
  kreise += '<circle cx="' + cx + '" cy="' + cy + '" r="220" fill="none" stroke="' + c.akzent + '" stroke-opacity="0.16" stroke-width="46"/>';
}
const flaeche = '<svg xmlns="http://www.w3.org/2000/svg" width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '">' + kreise
  + '<path d="' + welle + '" fill="' + c.primaer + '"/><path d="' + linie + '" fill="none" stroke="' + c.akzent + '" stroke-width="14" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const css = '*{margin:0;padding:0;box-sizing:border-box}'
  + 'html,body{width:1080px;height:1350px;overflow:hidden;background:' + c.hintergrund + ';color:' + c.text + ';font-family:' + fText + '}'
  + '.buehne{position:relative;width:1080px;height:1350px;overflow:hidden}.flaeche{position:absolute;top:0}'
  + '.kopf{position:absolute;top:72px;left:96px;right:96px;display:flex;align-items:center;gap:20px;font-family:' + fTitel + ';font-weight:600;font-size:30px;letter-spacing:0.02em}'
  + '.wort{display:inline-flex;align-items:center;justify-content:center;width:64px;height:64px;border-radius:50%;background:' + c.primaer + ';color:' + c.hintergrund + ';font-size:34px;font-weight:800}'
  + '.zaehler{margin-left:auto;font-size:28px;color:' + c.sekundaer + '}'
  + '.inhalt{position:absolute;left:96px;right:96px;top:220px}'
  + '.nr{font-family:' + fTitel + ';font-size:120px;font-weight:800;line-height:1;color:' + c.akzent + '}'
  + 'h1,h2{overflow-wrap:anywhere}h1{font-family:' + fTitel + ';font-size:78px;line-height:1.08;font-weight:800;margin-top:40px}'
  + 'h2{font-family:' + fTitel + ';font-size:62px;line-height:1.12;font-weight:800;margin-top:24px}'
  + 'p{font-size:38px;line-height:1.4;margin-top:32px;max-width:880px;overflow-wrap:anywhere}'
  + '.marke{display:inline-block;margin-top:44px;padding:14px 28px;border:4px solid ' + c.primaer + ';border-radius:999px;font-size:30px;font-weight:600;color:' + c.primaer + '}'
  + '.cta{display:inline-block;margin-top:44px;padding:24px 38px;border-radius:24px;background:' + c.primaer + ';color:' + c.hintergrund + ';font-family:' + fTitel + ';font-size:40px;font-weight:800}'
  + '.fuss{position:absolute;left:96px;right:96px;bottom:56px;display:flex;justify-content:space-between;font-size:24px;color:' + c.hintergrund + '}';
// Layoutvariante je Paket festlegen (stabil aus der paket_id), wie die drei Layouts aus Projekt 1.
let hash = 0; for (const ch of String(ctx.paket_id)) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
const stil = ['hybrid', 'thema', 'ablauf'][hash % 3];
const layoutCss = stil === 'thema' ? '.nr{display:none}.inhalt{top:300px}.marke{border-radius:0}.flaeche{opacity:.35}'
  : (stil === 'ablauf' ? '.nr{font-size:72px}.marke{border-radius:12px}.inhalt{top:200px}'
    : '.kopf{border-bottom:3px solid ' + c.akzent + ';padding-bottom:24px}.marke{border-radius:999px}');
const zwei = z => String(z).padStart(2, '0');
const kopf = i => '<div class="kopf">' + logo + '<span>' + esc(k.name) + '</span><span class="zaehler">' + zwei(i + 1) + '/' + zwei(n) + '</span></div>';
const fuss = '<div class="fuss"><span></span><span>' + esc(k.name) + '</span></div>';
const seite = koerper => '<!doctype html><html lang="de"><head><meta charset="utf-8"><style>' + css + layoutCss + '</style></head><body><div class="buehne">' + koerper + '</div></body></html>';
const items = [];
const basis = { paket_id: ctx.paket_id, kuerzel: ctx.kuerzel, bild_quelle: quelle, bild_hinweis: hinweis, ki_bild: quelle === 'flux', layout: stil, photo_credit: credit };
for (let i = 0; i < n; i++) {
  const f = folien[i];
  let mitte;
  if (f.type === 'titel') {
    const foto = bild ? '<div style="position:absolute;left:0;right:0;top:0;height:520px;background:url(' + bild + ') center/cover"></div>' : '';
    mitte = foto + '<div class="inhalt" style="top:' + (bild ? 580 : 220) + 'px"><h1>' + esc(f.heading) + '</h1><p>' + esc(f.text) + '</p><span class="marke">' + esc(k.name) + '</span></div>';
  } else if (f.type === 'abschluss') {
    mitte = '<div class="inhalt"><div class="nr">' + zwei(i + 1) + '</div><h2>' + esc(f.heading) + '</h2><p>' + esc(f.text) + '</p><span class="cta">' + esc(k.name) + '</span></div>';
  } else {
    mitte = '<div class="inhalt"><div class="nr">' + zwei(i) + '</div><h2>' + esc(f.heading) + '</h2><p>' + esc(f.text) + '</p></div>';
  }
  const html = seite('<div class="flaeche" style="left:-' + (i * B) + 'px">' + flaeche + '</div>' + kopf(i) + mitte + fuss);
  const datei = 'folie-' + zwei(i + 1) + '.png';
  const bin = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
  items.push({ json: Object.assign({ kind: 'folie', index: i + 1, file_name: datei, path: ctx.kuerzel + '/' + ctx.paket_id + '/' + datei, html_chars: html.length }, basis), binary: { index_html: bin }, pairedItem: { item: 0 } });
}
// Einzelbild (LinkedIn): Foto oder KI-Bild als Fläche, darüber der Titel der ersten Folie; ohne Bild ein Farbverlauf.
const hintergrund = bild ? 'url(' + bild + ') center/cover' : 'linear-gradient(135deg,' + c.primaer + ',' + c.akzent + ')';
let eb = '<div style="position:absolute;inset:0;background:' + hintergrund + '"></div><div style="position:absolute;inset:0;background:rgba(0,0,0,.38)"></div>';
eb += '<div class="kopf" style="color:#fff;border:0">' + logo + '<span>' + esc(k.name) + '</span></div>';
eb += '<div style="position:absolute;left:72px;right:72px;top:420px;background:' + c.hintergrund + ';color:' + c.text + ';padding:44px;border-radius:24px;font-family:' + fTitel + ';font-size:64px;line-height:1.1;font-weight:800;overflow-wrap:anywhere">' + esc(folien[0].heading) + '</div>';
if (credit && credit.source) eb += '<div style="position:absolute;left:72px;bottom:48px;color:#fff;font-size:22px">Foto: ' + esc(credit.photographer || '') + ' / Pixabay</div>';
const ebHtml = '<!doctype html><html lang="de"><head><meta charset="utf-8"><style>' + css + '</style></head><body><div class="buehne">' + eb + '</div></body></html>';
const ebBin = await this.helpers.prepareBinaryData(Buffer.from(ebHtml, 'utf8'), 'index.html', 'text/html');
items.push({ json: Object.assign({ kind: 'einzelbild', index: 0, file_name: 'einzelbild.png', path: ctx.kuerzel + '/' + ctx.paket_id + '/einzelbild.png', html_chars: ebHtml.length }, basis), binary: { index_html: ebBin }, pairedItem: { item: 0 } });
return items;

// Soll gegen Ist: jedes gerenderte Bild muss hochgeladen sein, die Pfade müssen zur Render-Liste passen. Sonst Fehler statt einer unvollständigen Meldung.
const agg = $input.first().json || {};
const keys = Array.isArray(agg.keys) ? agg.keys : [];
const liste = $('Render-Liste bauen [Code]').all();
const soll = liste.length;
if (soll < 6) throw new Error('Bilder: Render-Liste zu kurz.');
const meta = liste[0].json;
const pfade = keys.map(p => String(p).replace(/^k1-medien\//, '')).sort();
if (keys.length !== soll) throw new Error('Bilder: ' + keys.length + ' von ' + soll + ' hochgeladen.');
const erwartet = liste.map(i => i.json.path).sort();
if (pfade.some((p, i) => p !== erwartet[i])) throw new Error('Bilder: hochgeladene Pfade passen nicht zur Render-Liste.');
return [{ json: { paket_id: meta.paket_id, pfade: pfade, quelle: meta.bild_quelle, ki_bild: !!meta.ki_bild, hinweis: String(meta.bild_hinweis || '').slice(0, 300), anzahl: pfade.length, folien: soll - 1 } }];

// Rückgabe an den Agenten: kurzer Text, nur das Nötige. Die Bildpfade stehen im Paket (Spalte bilder), der Agent muss sie nicht weitergeben.
const b = $('Bilder prüfen [Code]').first().json;
const row = $input.first().json || {};
if (row.paket_id !== b.paket_id) throw new Error('Bilder: Vermerk im Paket nicht bestätigt.');
const quellen = { pixabay: 'Foto von Pixabay', flux: 'KI-Bild (FLUX)', farbverlauf: 'Farbverlauf ohne Foto' };
const zeilen = ['STATUS: OK', 'paket_id: ' + b.paket_id, 'bilder: ' + b.anzahl + ' (' + b.folien + ' Folien und 1 Einzelbild)', 'bildquelle: ' + (quellen[b.quelle] || b.quelle), 'ki_bild: ' + (b.ki_bild ? 'ja' : 'nein')];
if (b.hinweis) zeilen.push('hinweis: ' + b.hinweis);
zeilen.push('Die Bilder sind beim Paket vermerkt. Rufe als Nächstes Zur_Freigabe_einreichen mit der paket_id auf.');
return [{ json: { antwort: zeilen.join('\n'), paket_id: b.paket_id, anzahl: b.anzahl, quelle: b.quelle, ki_bild: b.ki_bild } }];

// Fehlerausgänge können den Kontext verlieren. Den geprüften Kontext gezielt wiederherstellen und mit dem KI-Bild weitermachen.
const basis = $('Branding wählen [Code]').first().json;
let notiz = '';
try { notiz = String($('Foto auswerten [Code]').first().json.photo_note || ''); } catch (e) { notiz = ''; }
const fehler = $input.first().json || {};
const grund = fehler.error ? String(fehler.error.message || fehler.error).slice(0, 160) : '';
return [{ json: { ...basis, photo_ok: false, photo_url: '', photo_data_uri: '', photo_credit: null,
  photo_note: notiz || ('Pixabay-Fotopfad gescheitert' + (grund ? ' (' + grund + ')' : '') + ', weiter mit KI-Bild.') }, pairedItem: { item: 0 } }];
